from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_account_dict, get_stock_daily_data, rebalance_to_weights
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
# Current Screener ensemble: deliberately excludes redundant session signals.
FACTOR_WEIGHTS = {"clv": .30, "peer": .23, "mom20": .18, "rev5": .18, "shortrev3": .11}
MIN_W, MAX_W, CADENCE_DAYS = .02, .14, 10
last_decision = None


def rank(values):
    out = {s: .5 for s in UNIVERSE}
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    if len(valid) > 1:
        for i, (s, _) in enumerate(valid):
            out[s] = (i + 1.0) / len(valid)
    return out


def bounded_simplex(raw):
    w = {s: min(MAX_W, max(MIN_W, float(raw.get(s, MIN_W)))) for s in UNIVERSE}
    # Iterative water filling preserves the complete, bounded portfolio.
    for _ in range(100):
        gap = 1.0 - sum(w.values())
        free = [s for s in UNIVERSE if MIN_W + 1e-10 < w[s] < MAX_W - 1e-10]
        if not free or abs(gap) < 1e-10:
            break
        for s in free:
            w[s] = min(MAX_W, max(MIN_W, w[s] + gap / len(free)))
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_decision
    account = get_account_dict()
    data = {}
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=110)
        if df is None or len(df) < 30:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        c = np.asarray(df["close"], float)
        o = np.asarray(df["open"], float)
        h = np.asarray(df["high"], float)
        lo = np.asarray(df["low"], float)
        r = c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
        data[symbol] = (c, o, h, lo, r, str(df.iloc[-1]["date"]))
    if len(data) < 12:
        return
    decision_date = max(x[5] for x in data.values())
    if last_decision is not None:
        try:
            elapsed = (np.datetime64(decision_date, "D") - np.datetime64(last_decision, "D")) / np.timedelta64(1, "D")
            if elapsed < CADENCE_DAYS:
                return
        except Exception:
            return

    clv, peer, mom20, rev5, shortrev3, invvol = ({}, {}, {}, {}, {}, {})
    five = {}
    for s, (c, o, h, lo, r, _) in data.items():
        if len(r) < 22:
            continue
        vol = max(float(np.std(r[-20:])), .008)
        invvol[s] = 1.0 / vol
        five[s] = c[-1] / max(c[-6], 1e-12) - 1.0
        # Smoothed CLV uses the last three completed bars to reduce turnover.
        locs = (2*c[-3:] - h[-3:] - lo[-3:]) / np.maximum(h[-3:] - lo[-3:], 1e-12)
        clv[s] = float(np.mean(locs))
        rev5[s] = -float(np.mean(r[-5:]))
        shortrev3[s] = -float(np.mean(r[-3:]))
        mom20[s] = (c[-1] / max(c[-21], 1e-12) - 1.0) / vol
    med = float(np.median(list(five.values())))
    peer = {s: v - med for s, v in five.items()}
    raw = {"clv": clv, "peer": peer, "mom20": mom20, "rev5": rev5, "shortrev3": shortrev3}
    ranked = {k: rank(v) for k, v in raw.items()}
    score = {s: sum(FACTOR_WEIGHTS[k] * ranked[k][s] for k in FACTOR_WEIGHTS) for s in UNIVERSE}

    # Medium-high risk: confirm weakness with both short and intermediate SPX trend.
    bearish = False
    if "SPX" in data:
        spx = data["SPX"][0]
        bearish = spx[-1] < spx[-6] and spx[-1] < spx[-21]
    if bearish:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += .14
        for s in ("BTC", "ETH", "WTI"):
            score[s] = max(.05, score[s] - .08)

    # 75% factor score / 25% inverse volatility: fully invested, no cash sleeve.
    avg_inv = float(np.mean(list(invvol.values()))) if invvol else 1.0
    raw_weight = {s: max(.01, score[s]) * (.75 + .25 * invvol.get(s, avg_inv) / avg_inv) for s in UNIVERSE}
    weights = bounded_simplex(raw_weight)
    scores = np.asarray([score[s] for s in UNIVERSE], float)
    sd = max(float(scores.std()), 1e-9)
    forecast = {s: float(.01 * (score[s] - scores.mean()) / sd) for s in UNIVERSE}

    factor_ids = []
    try:
        ensemble = json.loads((Path(__file__).parent / "factors" / "factor_ensemble.json").read_text(encoding="utf-8"))
        factor_ids = [x["factor_id"] for x in ensemble.get("selected_factors", [])
                      if isinstance(x, dict) and x.get("factor_id")]
    except Exception:
        pass
    rebalance_to_weights(weights, forecast_returns=forecast, factor_ids=factor_ids[:10], horizon_days=10)
    last_decision = decision_date
